LinkedList *mergeLinkedList(LinkedList *list1, LinkedList *list2){
    LinkedList * ans = new LinkedList();
    Node *l1 = list1->getHead();
    Node *l2 = list2->getHead();
    while(l1 || l2){
        if(l1 && l2){
            if(l1->getValue() < l2->getValue()){
                ans->add(l1->getValue());
                l1 = l1->getNextNode();
            }
            else{
                ans->add(l2->getValue());
                l2 = l2->getNextNode();
            }
        }
        else if(l1 && !l2){
            ans->add(l1->getValue());
            l1 = l1->getNextNode();
        }
        else if(l2 && !l1){
            ans->add(l2->getValue());
            l2 = l2->getNextNode();
